INSERT INTO groups (slug, name, tagline, description, interests, owner_name, owner_role, status, image, joining_note, is_sample, sort) VALUES
('music-club', 'IMC Music Club', 'Where melodies bring people together.', 'Acoustic jams, open mics and singalongs for singers, players and people who just love music. Bring an instrument or just your voice.', '["music"]', 'Neeyati', 'Captain, Music Community', 'active', 'photo:danceCrowd3', 'Open to everyone. Beginners welcome; no audition.', 1, 1),
('nature-retreat', 'Nature Retreat', 'Find peace in the wild.', 'Treks, trails and weekend getaways around the Seshachalam hills. Slow mornings, muddy shoes and sunrise views.', '["outdoors","fitness"]', 'Tharun Reddy', 'Captain, Nature Retreat', 'active', 'photo:hilltop', 'Basic fitness needed for treks; every outing lists its difficulty.', 1, 2),
('sports-club', 'IMC Sports Club', 'Play hard, stay fit.', 'Box cricket, morning runs, volleyball and turf games for every skill level.', '["fitness"]', 'Uday', 'Captain, Cricket Club', 'active', 'photo:nightCricket', 'All levels. Teams are mixed so newcomers always get a game.', 1, 3),
('book-club', 'Book Club', 'Many readers, one story.', 'Monthly reads in English and Telugu, and conversations that go well past the last page.', '["books"]', 'Rohitha Reddy', 'Captain, Book Club', 'active', 'photo:bookClub', 'Read along or just come to listen.', 1, 4),
('dance-club', 'Dance Club', 'Express through movement.', 'Folk, classical, Bollywood and freestyle sessions, from first steps to stage performances.', '["dance"]', 'Ajay Varma', 'Captain, Dance Club', 'active', 'photo:classicalDance', 'No experience needed. Wear comfortable clothes.', 1, 5),
('cycling-club', 'Cycling Club', 'Early starts, open roads.', 'Sunrise rides around Tirupati, from easy town loops to the road to Chandragiri.', '["fitness","outdoors"]', 'Ravee', 'Captain, Cycling Club', 'active', 'photo:bikeRide', 'Bring your own cycle and a helmet.', 1, 6),
('art-craft', 'Art & Craft Club', 'Make something with your hands.', 'Kalamkari, painting, clay and sketch walks with local artists.', '["art","photography"]', 'IMC core team', 'Club host', 'active', 'photo:artTable', 'Materials provided at most sessions; the event page says if you need to bring anything.', 1, 7),
('startup-club', 'Startup Club', 'From idea to impact.', 'Founders, students and professionals trading notes over chai: pitches, feedback and career help.', '["entrepreneurship","careers"]', 'IMC core team', 'Club host', 'active', 'photo:roundTable', 'Builders, students and the curious all welcome.', 1, 8);
INSERT INTO events (slug, title, group_id, category, summary, description, start_at, end_at, venue, address, area, price_inr, price_note, capacity, organizer_name, image, beginner_friendly, first_timer_note, age_note, accessibility_note, cancellation_terms, status, is_sample) VALUES
('seven-hills-unplugged', 'Seven Hills Unplugged', (SELECT id FROM groups WHERE slug='music-club'), 'music', 'An acoustic evening on the terrace.', 'Bring a song, a guitar, or just your voice for the chorus. Short sets of two songs each; sign up for a slot when you arrive or simply enjoy the music.', '2026-10-31T18:30', '2026-10-31T21:00', 'Banyan Courtyard Café', 'Tilak Road, Tirupati', 'Tilak Road', 199, 'Includes one drink', 40, 'IMC Music Club', 'https://images.unsplash.com/photo-1791326457073-2fcd8ff789b7?auto=format&fit=crop&w=1200&q=75', 1, 'A host meets first-timers at the entrance and introduces you around. You do not have to perform.', 'All ages; under-16s with an adult.', 'Terrace reached by stairs; tell us if you need a ground-floor seat.', 'Full refund if you cancel 24 hours before.', 'scheduled', 1),
('alipiri-run-club', 'Alipiri Morning Run Club', (SELECT id FROM groups WHERE slug='sports-club'), 'sports', 'A friendly 5K at the foot of the hills.', 'All paces welcome; we regroup at every kilometre. Idli and chai after the run.', '2026-11-02T05:45', '2026-11-02T07:30', 'Alipiri bus stop', 'Alipiri, Tirupati', 'Alipiri', 0, '', 0, 'IMC Sports Club', 'photo:hillsTrek', 1, 'Look for the IMC flag at the bus stop. Walk-runners are very welcome.', '16+', 'Road route with a gentle slope.', 'Free; just let us know if you cannot make it.', 'scheduled', 1),
('talakona-trail-weekend', 'Talakona Trail Weekend', (SELECT id FROM groups WHERE slug='nature-retreat'), 'nature', 'A forest trail to the waterfall.', 'A guided forest walk to the falls with a slow breakfast by the stream. Moderate walking of about 6 km in total.', '2026-11-08T05:30', '2026-11-08T17:00', 'Pickup at Alipiri Circle', 'Alipiri Circle, Tirupati', 'Alipiri', 1499, 'Includes transport and breakfast', 25, 'Nature Retreat', 'photo:waterfall', 0, '', '12+', 'Uneven forest paths; not wheelchair accessible.', 'Full refund up to 72 hours before; after that, 50%.', 'scheduled', 1),
('kalamkari-canvas-lab', 'Kalamkari Canvas Lab', (SELECT id FROM groups WHERE slug='art-craft'), 'culture', 'Learn the pen-and-natural-dye art of nearby Srikalahasti.', 'A local artist walks you through Kalamkari outlines and natural colours. Take your piece home.', '2026-11-08T16:00', '2026-11-08T18:30', 'Makers'' Loft', 'Air Bypass Road, Tirupati', 'Air Bypass Road', 699, 'Includes all materials', 20, 'Art & Craft Club', 'photo:craftCircle', 1, 'No drawing skills needed; you will trace and colour a design.', 'All ages; under-12s with an adult.', 'Ground-floor studio.', 'Full refund if you cancel 48 hours before.', 'scheduled', 1),
('ruchulu-food-walk', 'Rayalaseema Ruchulu Food Walk', NULL, 'food', 'A breakfast crawl through the old town.', 'Pesarattu, ghee karam dosa and filter coffee across four local spots, with stories about each.', '2026-11-09T07:00', '2026-11-09T09:30', 'Starts at Gandhi Road', 'Gandhi Road, Tirupati', 'Gandhi Road', 349, 'Food included', 15, 'IMC Culture & Lifestyle', 'https://images.unsplash.com/photo-1694849789325-914b71ab4075?auto=format&fit=crop&w=1200&q=75', 1, 'Small group of 15, so it is easy to chat. Come hungry.', 'All ages.', 'About 2 km of walking on busy streets.', 'Full refund if you cancel 24 hours before.', 'scheduled', 1),
('chandragiri-heritage-ride', 'Chandragiri Fort Heritage Ride', (SELECT id FROM groups WHERE slug='cycling-club'), 'sports', 'A sunrise ride to the Vijayanagara-era fort.', 'An easy-paced ride out to Chandragiri with a short history walk at the top. Support vehicle follows the group.', '2026-11-09T05:30', '2026-11-09T10:00', 'SV University main gate', 'SV University, Tirupati', 'SV University', 0, 'Bring your own cycle', 30, 'Cycling Club', 'photo:bikeRide', 0, '', '16+', 'Road ride of about 30 km return.', 'Free; tell us if you drop out so the support van knows.', 'scheduled', 1),
('temple-city-founders-chai', 'Temple City Founders'' Chai', (SELECT id FROM groups WHERE slug='startup-club'), 'startup', 'Three five-minute pitches and a lot of chai.', 'Founders pitch, the room gives honest feedback, then open networking. Builders, students and the curious.', '2026-11-12T19:00', '2026-11-12T21:00', 'The Hub', 'Bhavani Nagar, Tirupati', 'Bhavani Nagar', 99, '', 30, 'Startup Club', 'photo:roundTable', 1, 'You do not need a startup to come; most people come to listen.', '18+', 'Ground floor.', 'Full refund if you cancel 24 hours before.', 'scheduled', 1),
('board-games-night', 'Board Games Night', NULL, 'meetups', 'Catan, carrom and chaos.', 'Bring a game or learn a new one. Tables are mixed so you meet new people.', '2026-11-14T18:00', '2026-11-14T21:00', 'Banyan Courtyard Café', 'Tilak Road, Tirupati', 'Tilak Road', 149, 'Includes snacks', 12, 'IMC Board Games', 'photo:carrom', 1, 'Rules are explained at every table.', 'All ages.', 'Ground floor.', 'Full refund if you cancel 24 hours before.', 'scheduled', 1),
('swarnamukhi-sketch-walk', 'Swarnamukhi Sunset Sketch Walk', (SELECT id FROM groups WHERE slug='art-craft'), 'culture', 'Capture the river at golden hour.', 'Sketchbooks and phones out. We walk, stop, draw and share what we made.', '2026-11-15T16:30', '2026-11-15T18:30', 'Riverside, near the old bridge', 'Swarnamukhi riverside, Tirupati', 'Swarnamukhi', 0, '', 20, 'Art & Craft Club', 'photo:artTable', 1, 'Any skill level; phones count as sketchbooks.', 'All ages.', 'Riverside path, some uneven ground.', 'Free.', 'scheduled', 1),
('filter-coffee-strangers', 'Filter Coffee & Strangers', NULL, 'meetups', 'Small tables, simple prompts, real conversations.', 'New to the city or just want new friends? Hosts keep tables small and conversation easy.', '2026-11-16T10:00', '2026-11-16T12:00', 'Banyan Courtyard Café', 'Tilak Road, Tirupati', 'Tilak Road', 149, 'Includes coffee', 24, 'Connect Tirupati', 'photo:meetup', 1, 'Made for people who come alone. Introvert mode can remain on.', '18+', 'Ground floor.', 'Full refund if you cancel 24 hours before.', 'scheduled', 1),
('palm-leaf-pages', 'Palm-Leaf Pages Book Circle', (SELECT id FROM groups WHERE slug='book-club'), 'culture', 'Short stories from Telugu writers.', 'This month we read short stories by Telugu writers, in English and Telugu. Read ahead or just listen.', '2026-11-19T18:00', '2026-11-19T19:30', 'Reading room, Makers'' Loft', 'Air Bypass Road, Tirupati', 'Air Bypass Road', 0, '', 20, 'Book Club', 'photo:bookTable', 1, 'You do not need to have read the stories.', 'All ages.', 'Ground floor.', 'Free.', 'scheduled', 1),
('horsley-starlight-camp', 'Horsley Hills Starlight Camp', (SELECT id FROM groups WHERE slug='nature-retreat'), 'nature', 'Tents, a bonfire and a sky full of stars.', 'Overnight camp at Horsley Hills. Back in Tirupati by Sunday lunch.', '2026-11-22T14:00', '2026-11-23T13:00', 'Pickup at Tirupati bus stand', 'Tirupati bus stand', 'Bus stand', 2999, 'Includes transport, tent and meals', 20, 'Nature Retreat', 'photo:hilltop', 0, '', '16+', 'Camping on uneven ground; basic toilets.', 'Full refund up to 7 days before; after that, 50%.', 'scheduled', 1),
('kapila-sunrise-yoga', 'Sunrise Yoga by the Steps', NULL, 'sports', 'Gentle yoga at sunrise.', 'A beginners'' session near Kapila Theertham.', '2026-11-29T06:00', '2026-11-29T07:00', 'Near Kapila Theertham', 'Kapila Theertham Road, Tirupati', 'Kapila Theertham', 0, '', 30, 'IMC Sports Club', 'photo:outdoorSelfie', 1, 'Bring a mat or towel.', 'All ages.', 'Open ground.', 'Free.', 'cancelled', 1);
INSERT INTO rsvps (event_id, ref, name, contact, party_size, status) VALUES
((SELECT id FROM events WHERE slug='board-games-night'), 'SAMPLE-FULL', 'Sample booking (group)', 'sample', 12, 'confirmed');
INSERT INTO stories (slug, title, summary, body, photos, group_id, event_date, consent_confirmed, status, is_sample) VALUES
('nature-retreat-falls', 'A morning at the falls', 'Proof that we actually touched grass this weekend.', 'Twenty-odd people, one forest trail and a waterfall at the end of it. Breakfast by the stream turned into an hour of stories. Next outing: Talakona Trail Weekend.', '["waterfall","hilltop","hillsTrek"]', (SELECT id FROM groups WHERE slug='nature-retreat'), '2026-09-21', 1, 'published', 1),
('art-club-full-house', 'First table, full house', 'The Art & Craft Club''s first session filled the room.', 'Clay, colours and a long table of people who had never met. Half the room stayed back to plan the next one.', '["artTable","craftCircle"]', (SELECT id FROM groups WHERE slug='art-craft'), '2026-08-30', 1, 'published', 1),
('dance-night-recap', 'The dance night that ended in a group photo', 'From first steps to a full-floor finale.', 'Folk, classical and a lot of laughing. Nobody needed experience, and everybody ended up in the photo.', '["danceCrowd","classicalDance","danceStudio"]', (SELECT id FROM groups WHERE slug='dance-club'), '2026-09-07', 1, 'published', 1),
('book-club-twelve-readers', 'Twelve readers, one story', 'The Book Club''s monthly circle.', 'One short story, twelve readings of it. The best part was hearing the same page in English and Telugu.', '["bookClub","bookTable"]', (SELECT id FROM groups WHERE slug='book-club'), '2026-10-05', 1, 'published', 1);
INSERT INTO opportunities (title, kind, compensation, eligibility, deadline, description, how_to_apply, posted_by, status, is_sample) VALUES
('Event photographer: Talakona Trail Weekend', 'paid', '₹1,500 for the day', 'Own camera; share a portfolio link', '2026-11-05', 'Capture the trail and the falls for the recap and the Memory Wall. Travel and breakfast included.', 'Message IMC on WhatsApp with your portfolio link.', 'Nature Retreat', 'published', 1),
('Welcome desk volunteers', 'volunteer', 'Voluntary (unpaid)', 'Friendly, 18+, free on event mornings', '2026-11-10', 'Greet first-timers, help them find their table or group, and make the first five minutes easy.', 'Message IMC on WhatsApp saying "welcome desk".', 'IMC core team', 'published', 1),
('Reel editor for monthly recaps', 'paid', '₹800 per reel', 'Comfortable with short-form video; share two samples', '2026-11-15', 'Turn event footage into a 30-second recap each month.', 'Message IMC on WhatsApp with two sample reels.', 'IMC core team', 'published', 1),
('Co-host: Filter Coffee & Strangers', 'collab', 'Voluntary (unpaid)', 'Good listener; has attended at least one IMC meetup', '2026-11-12', 'Help hosts keep tables small and conversations easy.', 'Message IMC on WhatsApp saying "co-host".', 'Connect Tirupati', 'published', 1);
INSERT INTO adda_posts (kind, title, body, category, author_name, poll_options, status, admin_note, published, is_sample) VALUES
('poll', 'What should IMC start next in Tirupati?', 'Vote for the one you would actually show up to.', 'community', 'IMC core team', '["Weekend trekking club","Telugu theatre circle","Sunday clean-up drive","Chess and board games league"]', 'received', '', 1, 1),
('idea', 'Monthly clean-up at the Kapila Theertham steps', 'One Sunday morning a month, an hour of picking up plastic, then breakfast together.', 'environment', 'Sample member', '[]', 'planned', 'Talking to volunteers; the first date will be announced here.', 1, 1),
('question', 'Quiet place for a study group near SV University?', 'Looking for somewhere with tables and Wi-Fi for 5 to 6 people on weekends.', 'places', 'Sample member', '[]', 'completed', 'IMC answer: the Makers'' Loft reading room is free on Saturday mornings; message us to book a table.', 1, 1),
('recommendation', 'Filter coffee after an early train', 'Arriving at dawn? The coffee near the railway station sorts you out before you plan the day.', 'food', 'Sample member', '[]', 'completed', '', 1, 1);
